def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = None

        # Split pre-release (after '-')
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)
        # If no pre-release, it sorts after the same version with pre-release
        # So we use a tuple where no pre-release is represented by a high value
        if not prerelease_identifiers:
            prerelease_sort = (1,)
        else:
            prerelease_sort = (0, tuple(prerelease_identifiers))

        return (major, minor, patch, prerelease_sort)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

